extern "C" int strcmp(const char*, const char*);

class nglFixedString
{
public:
  typedef unsigned long long fint;
  enum { STR_SIZE = 32, NUM_FINTS = 4 };
  typedef nglFixedString FS;

  fint* value() { return reinterpret_cast<fint*>(str); }
  const fint* value() const { return reinterpret_cast<const fint*>(str); }

  const FS& operator=(const FS& rhs)
  {
    for (int i = 0; i < NUM_FINTS; ++i)
      value()[i] = rhs.value()[i];
    return *this;
  }

  bool operator==(const FS& rhs) const
  {
    for (int i = 0; i < NUM_FINTS; ++i)
      if (!(value()[i] == rhs.value()[i]))
        return false;
    return true;
  }

  bool operator>=(const FS& rhs)
  {
    return strcmp(&str[0], &rhs.str[0]) >= 0;
  }

private:
  char str[STR_SIZE];
} __attribute__((aligned(8)));

class nglInstanceBank
{
public:
  struct Instance
  {
    nglFixedString Key;
    void* Value;
    int RefCount;
    Instance* Forward[1];
  };

  Instance* NIL;
  Instance* Head;
  Instance* Insert(const nglFixedString& Key, void* Value);

private:
  enum { MaxNumberOfLevels = 16 };
  int RandomsLeft;
  int RandomBits;
  int Level;
  Instance* NewNodeOfLevel(int l);
  int RandomLevel();
};

nglInstanceBank::Instance* nglInstanceBank::Insert(const nglFixedString& Key, void* Value)
{
  int k;
  Instance* update[MaxNumberOfLevels];
  Instance* p;
  Instance* q;
  p = Head;
  k = Level;
  do
  {
    for (;;)
    {
      q = p->Forward[k];
      if (q->Key >= Key) break;
      p = q;
    }
    update[k] = p;
  } while(--k >= 0);
  if (q->Key == Key)
  {
    q->RefCount++;
    return q;
  }
  k = RandomLevel();
  if (k > Level)
  {
    k = ++Level;
    update[k] = Head;
  };
  q = NewNodeOfLevel(k);
  q->Key = Key;
  q->Value = Value;
  q->RefCount = 1;
  do
  {
    p = update[k];
    q->Forward[k] = p->Forward[k];
    p->Forward[k] = q;
  } while(--k >= 0);
  return 0;
}
